package com.example.code.data

import com.example.code.controller.ratingFromDocument
import com.example.code.controller.campsiteOwnerUpdateToMap
import com.example.code.model.Campsite
import com.example.code.model.Rating
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertThrows
import org.junit.Test

class CampsiteRatingPersistenceTest {
    @Test fun ownerEditsCannotOverwriteTheDisplayedRatingOrItsTotals() {
        val fields = campsiteOwnerUpdateToMap(Campsite(id = "jasper", name = "New name", rating = 1.0))
        assertEquals("New name", fields["name"])
        assertEquals(emptySet<String>(), fields.keys.intersect(setOf("rating", "averageRating", "ratingSum", "ratingCount")))
        assertEquals(false, fields.containsKey("ownerId"))
    }

    @Test fun savedRatingRoundTripsThroughTheExistingAdminParser() {
        val rating = Rating("stay-1", "priya", "jasper", 4, "stay-1")
        assertEquals(rating, ratingFromDocument(rating.id, stayRatingToMap(rating)))
    }

    @Test fun legacyRatingWithoutAStayRemainsReadable() {
        val rating = ratingFromDocument("console-rating", mapOf("campsiteId" to "jasper", "score" to 5L))!!
        assertEquals("", rating.reservationId)
        assertEquals(5, rating.score)
    }

    @Test fun firstRatingSetsTheMeanAndCount() {
        val next = updatedRatingTotals(RatingTotals(0, 0), null, 4)
        assertEquals(RatingTotals(4, 1), next)
        assertEquals(4.0, next.average!!, 0.0)
    }

    @Test fun replacementAdjustsOnlyTheScoreAndPreservesTheCount() {
        val next = updatedRatingTotals(RatingTotals(6, 2), 1, 4)
        assertEquals(RatingTotals(9, 2), next)
        assertEquals(4.5, next.average!!, 0.0)
    }

    @Test fun resubmittingTheSameScoreDoesNotInflateCountOrSum() {
        assertEquals(RatingTotals(9, 2), updatedRatingTotals(RatingTotals(9, 2), 4, 4))
    }

    @Test fun lastRemovalClearsTheDisplayedRating() {
        val next = updatedRatingTotals(RatingTotals(5, 1), 5, null)
        assertEquals(RatingTotals(0, 0), next)
        assertNull(next.average)
    }

    @Test fun removingOneRatingKeepsTheRemainingContributions() {
        val next = updatedRatingTotals(RatingTotals(9, 3), 1, null)
        assertEquals(RatingTotals(8, 2), next)
        assertEquals(4.0, next.average!!, 0.0)
    }

    @Test fun existingConsoleRatingsAndANewStayAllContribute() {
        // Initial totals of two legacy ratings, 5 and 1, read during bootstrap.
        val next = updatedRatingTotals(RatingTotals(6, 2), null, 3)
        assertEquals(RatingTotals(9, 3), next)
        assertEquals(3.0, next.average!!, 0.0)
    }

    @Test fun submitUpdateAndAdminRemovalRemainConsistentInEitherSerializedOrder() {
        val afterUpdate = updatedRatingTotals(RatingTotals(6, 2), 1, 4)
        val updateThenRemove = updatedRatingTotals(afterUpdate, 5, null)
        val afterRemove = updatedRatingTotals(RatingTotals(6, 2), 5, null)
        val removeThenUpdate = updatedRatingTotals(afterRemove, 1, 4)
        assertEquals(RatingTotals(4, 1), updateThenRemove)
        assertEquals(updateThenRemove, removeThenUpdate)
    }

    @Test fun manyUpdatesDoNotAccumulateFloatingPointDrift() {
        var totals = RatingTotals(8, 3)
        var score = 3
        repeat(1000) {
            val nextScore = it % 5 + 1
            totals = updatedRatingTotals(totals, score, nextScore)
            score = nextScore
        }
        assertEquals(RatingTotals(5L + score, 3), totals)
        assertEquals((5.0 + score) / 3.0, totals.average!!, 0.0)
    }

    @Test fun inconsistentTotalsFailRatherThanInventingAnAverage() {
        assertThrows(IllegalArgumentException::class.java) { updatedRatingTotals(RatingTotals(0, 0), 5, 3) }
        assertThrows(IllegalArgumentException::class.java) { updatedRatingTotals(RatingTotals(1, 1), 5, null) }
    }
}
